130→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
131→  const { t } = useTranslation();
132→  const { isStreaming, editMessage, deleteMessage, sendMessage, messages } = useAgent();
133→  const [isEditing, setIsEditing] = useState(false);
134→  const [editText, setEditText] = useState(message.content);
135→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
136→  const textareaRef = useRef<HTMLTextAreaElement>(null);
137→
138→  const isUser = message.role === 'user';
139→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
140→
141→  useEffect(() => {
142→    if (isEditing && textareaRef.current) {
143→      textareaRef.current.focus();
144→      textareaRef.current.selectionStart = textareaRef.current.value.length;
145→    }
146→  }, [isEditing]);
147→
148→  const handleEdit = () => {
149→    setEditText(message.content);
150→    setIsEditing(true);
151→    setIsConfirmingDelete(false);
152→  };
153→
154→  const handleCancelEdit = () => {
155→    setIsEditing(false);
156→    setEditText(message.content);
157→  };
158→
159→  const handleSaveEdit = () => {
160→    const trimmed = editText.trim();
161→    if (!trimmed || trimmed === message.content) {
162→      handleCancelEdit();
163→      return;
164→    }
165→    setIsEditing(false);
166→    editMessage(messageIndex, trimmed);
167→  };
168→
169→  const handleDeleteConfirm = () => {
170→    setIsConfirmingDelete(false);
171→    deleteMessage(messageIndex);
172→  };
173→
174→  const handleKeyDown = (e: React.KeyboardEvent) => {
175→    if (e.key === 'Escape') {
176→      handleCancelEdit();
177→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
178→      e.preventDefault();
179→      handleSaveEdit();
180→    }
181→  };
182→
183→  let streamingRemainder: string | undefined;
184→  if (hasSegments && message.isStreaming && message.content) {
185→    const segmentedText = message.segments!
186→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
187→      .map((s) => s.text || '')
188→      .join('');
189→    const remaining = message.content.slice(segmentedText.length);
190→    if (remaining.trim()) {
191→      streamingRemainder = remaining;
192→    }
193→  }
194→
195→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
196→  const isInAnswerPhase = message.currentPhase === 'answer';
197→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
198→
199→  const hasCharts = hasSegments && message.segments!.some(
200→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
201→  );
202→
203→  const answerBlockSegments = hasSegments
204→    ? message.segments!
205→        .filter((s) =>
206→          (s.type === 'answer' && s.text?.trim()) ||
207→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
208→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
209→          (s.type === 'subagent_end' && s.chart_spec)
210→        )
211→        .map((s) => {
212→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
213→            return { ...s, text: stripChartSpecBlocks(s.text) };
214→          }
215→          return s;
216→        })
217→        .filter((s) => {
218→          // Remove text segments that became empty after stripping chart blocks
219→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
220→            return false;
221→          }
222→          return true;
223→        })
224→    : [];
225→
226→  const questionSegments = hasSegments
227→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
228→    : [];
229→
230→  return (
231→    <div className={`message-bubble message-bubble--${message.role}`}>
232→      <div className="message-bubble__header">
233→        {isUser ? t('you') : t('assistant')}
234→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
235→          <span className="message-bubble__actions">
236→            <button
237→              className="message-bubble__action-btn"
238→              onClick={handleEdit}
239→              title={t('editMessage')}
240→            >
241→              &#9998;
242→            </button>
243→            <button
244→              className="message-bubble__action-btn message-bubble__action-btn--delete"
245→              onClick={() => setIsConfirmingDelete(true)}
246→              title={t('deleteMessage')}
247→            >
248→              &#128465;
249→            </button>
250→          </span>
251→        )}
252→      </div>
253→
254→      {isUser && isConfirmingDelete && (
255→        <div className="message-bubble__confirm-delete">
256→          <span>{t('deleteConfirm')}</span>
257→          <div className="message-bubble__confirm-actions">
258→            <button
259→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
260→              onClick={handleDeleteConfirm}
261→            >
262→              {t('delete')}
263→            </button>
264→            <button
265→              className="message-bubble__confirm-btn"
266→              onClick={() => setIsConfirmingDelete(false)}
267→            >
268→              {t('cancel')}
269→            </button>
270→          </div>
271→        </div>
272→      )}
273→
274→      {isUser && isEditing ? (
275→        <div className="message-bubble__edit-mode">
276→          <textarea
277→            ref={textareaRef}
278→            className="message-bubble__edit-textarea"
279→            value={editText}
280→            onChange={(e) => setEditText(e.target.value)}
281→            onKeyDown={handleKeyDown}
282→            rows={3}
283→          />
284→          <div className="message-bubble__edit-actions">
285→            <button
286→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
287→              onClick={handleSaveEdit}
288→            >
289→              {t('saveResend')}
290→            </button>
291→            <button
292→              className="message-bubble__edit-btn"
293→              onClick={handleCancelEdit}
294→            >
295→              {t('cancel')}
296→            </button>
297→          </div>
298→        </div>
299→      ) : hasSegments ? (
300→        <div className="message-bubble__segments">
301→          {!questionSegments.some((s) => !s.userAnswer) && (
302→            <ThinkingBlock
303→              segments={message.segments!}
304→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
305→              isThinkingPhase={isThinkingPhase}
306→              isAgentStreaming={!!message.isStreaming}
307→              hasAnswer={hasAnswer}
308→            />
309→          )}
310→          {questionSegments.map((seg, i) => (
311→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
312→              <UserQuestion
313→                questionData={seg.questionData!}
314→                userAnswer={seg.userAnswer}
315→                userFreeText={seg.userFreeText}
316→              />
317→            </div>
318→          ))}
319→          {answerBlockSegments.length > 0 && (
320→            <div className="message-bubble__segment message-bubble__segment--answer">
321→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
322→              {answerBlockSegments.map((seg, i) => {
323→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
324→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
325→                  return (
326→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
327→                      {seg.type === 'tool' && seg.toolResult ? (
328→                        <InlineQueryResult result={seg.toolResult!} />
329→                      ) : seg.chart_spec ? (
330→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
331→                      ) : null}
332→                    </div>
333→                  );
334→                }
335→                // Text segment (answer or subagent_end without chart_spec)
336→                return (
337→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
338→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
339→                  </div>
340→                );
341→              })}
342→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
343→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
344→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
345→                return displayText?.trim() ? (
346→                  <div className="message-bubble__segment-content">
347→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
348→                  </div>
349→                ) : null;
350→              })()}
351→            </div>
352→          )}
353→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
354→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
355→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
356→            return displayText?.trim() ? (
357→              <div className="message-bubble__segment message-bubble__segment--answer">
358→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
359→                <div className="message-bubble__segment-content">
360→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
361→                </div>
362→              </div>
363→            ) : null;
364→          })()}
365→          {message.segments!.filter((s) => s.type === 'error').map((seg, i) => {
366→            const lastUserMsg = messages.slice().reverse().find((m) => m.role === 'user');
367→            const handleRetry = lastUserMsg ? () => sendMessage(lastUserMsg.content) : undefined;
368→            return <ErrorBlock key={`error-${i}`} errorMessage={seg.errorMessage || 'Unknown error'} onRetry={!isStreaming ? handleRetry : undefined} />;
369→          })}
370→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
371→            <span className="message-bubble__typing">{t('thinking')}</span>
372→          )}
373→        </div>
374→      ) : (
375→        <>
376→          <div className="message-bubble__content">
377→            {message.content ? (
378→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
379→            ) : message.isStreaming ? (
380→              <span className="message-bubble__typing">{t('thinking')}</span>
381→            ) : null}
382→          </div>
383→          {message.toolCalls && message.toolCalls.length > 0 && (
384→            <div className="message-bubble__tools">
385→              {message.toolCalls.map((tc) => (
386→                <InlineQueryResult key={tc.toolCallId} result={tc} />
387→              ))}
388→            </div>
389→          )}
390→        </>
391→      )}
392→    </div>
393→  );
394→}
