  1→import { useState } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import { useAgent } from '../hooks/useAgent';
  4→import type { UserQuestionData } from '../types';
  5→import './UserQuestion.css';
  6→
  7→export function UserQuestion({
  8→  questionData,
  9→  userAnswer,
 10→  userFreeText,
 11→}: {
 12→  questionData: UserQuestionData;
 13→  userAnswer?: string[];
 14→  userFreeText?: string;
 15→}) {
 16→  const { t } = useTranslation();
 17→  const { respondToQuestion } = useAgent();
 18→  const [selected, setSelected] = useState<Set<string>>(new Set());
 19→  const [freeText, setFreeText] = useState('');
 20→  const [showFreeText, setShowFreeText] = useState(false);
 21→  const isAnswered = !!userAnswer;
 22→
 23→  const handleOptionClick = (label: string) => {
 24→    if (isAnswered) return;
 25→    if (questionData.multiSelect) {
 26→      setSelected((prev) => {
 27→        const next = new Set(prev);
 28→        if (next.has(label)) next.delete(label);
 29→        else next.add(label);
 30→        return next;
 31→      });
 32→    } else {
 33→      // Single-select: submit immediately
 34→      respondToQuestion(questionData.questionId, [label]);
 35→    }
 36→  };
 37→
 38→  const handleSubmitMulti = () => {
 39→    if (isAnswered) return;
 40→    const answers = [...selected];
 41→    if (showFreeText && freeText.trim()) {
 42→      respondToQuestion(questionData.questionId, answers, freeText.trim());
 43→    } else {
 44→      respondToQuestion(questionData.questionId, answers);
 45→    }
 46→  };
 47→
 48→  const handleSubmitFreeText = () => {
 49→    if (isAnswered || !freeText.trim()) return;
 50→    respondToQuestion(questionData.questionId, [], freeText.trim());
 51→  };
 52→
 53→  if (isAnswered) {
 54→    return (
 55→      <div className="user-question user-question--answered">
 56→        <div className="user-question__label">{t('questionAnswered')}</div>
 57→        <div className="user-question__question">{questionData.question}</div>
 58→        <div className="user-question__selected-answers">
 59→          {userAnswer.map((a, i) => (
 60→            <span key={i} className="user-question__selected-chip">{a}</span>
 61→          ))}
 62→          {userFreeText && (
 63→            <span className="user-question__selected-chip">{userFreeText}</span>
 64→          )}
 65→        </div>
 66→      </div>
 67→    );
 68→  }
 69→
 70→  return (
 71→    <div className="user-question">
 72→      <div className="user-question__label">{t('questionFromAgent')}</div>
 73→      <div className="user-question__question">{questionData.question}</div>
 74→      <div className="user-question__options">
 75→        {questionData.options.map((opt, i) => (
 76→          <button
 77→            key={i}
 78→            className={`user-question__option ${selected.has(opt.label) ? 'user-question__option--selected' : ''}`}
 79→            onClick={() => handleOptionClick(opt.label)}
 80→          >
 81→            {questionData.multiSelect && (
 82→              <span className="user-question__checkbox">
 83→                {selected.has(opt.label) ? '\u2611' : '\u2610'}
 84→              </span>
 85→            )}
 86→            <span className="user-question__option-label">{opt.label}</span>
 87→            {opt.description && (
 88→              <span className="user-question__option-desc">{opt.description}</span>
 89→            )}
 90→          </button>
 91→        ))}
 92→      </div>
 93→      <div className="user-question__free-text-toggle">
 94→        <button
 95→          className="user-question__other-btn"
 96→          onClick={() => setShowFreeText(!showFreeText)}
 97→        >
 98→          {showFreeText ? t('hideOther') : t('other')}
 99→        </button>
100→      </div>
101→      {showFreeText && (
102→        <div className="user-question__free-text">
103→          <input
104→            type="text"
105→            className="user-question__free-text-input"
106→            placeholder={t('typeYourAnswer')}
107→            value={freeText}
108→            onChange={(e) => setFreeText(e.target.value)}
109→            onKeyDown={(e) => {
110→              if (e.key === 'Enter' && !e.nativeEvent.isComposing) {
111→                e.preventDefault();
112→                handleSubmitFreeText();
113→              }
114→            }}
115→          />
116→          <button
117→            className="user-question__submit-btn"
118→            onClick={handleSubmitFreeText}
119→            disabled={!freeText.trim()}
120→          >
121→            {t('submit')}
122→          </button>
123→        </div>
124→      )}
125→      {questionData.multiSelect && selected.size > 0 && (
126→        <button className="user-question__submit-btn user-question__submit-multi" onClick={handleSubmitMulti}>
127→          {t('submit')} ({selected.size})
128→        </button>
129→      )}
130→    </div>
131→  );
132→}
